_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n6:[\"$\",\"$L22\",null,{\"pageId\":2160,\"activeView\":{\"name\":\"default\",\"activeViewSuffix\":\"\",\"language\":\"en\"},\"children\":\"$@23\"}]\n9:null\ne:[[\"$\",\"title\",\"0\",{\"children\":\"Bhagavad-gītā As It Is 7.9\"}],[\"$\",\"meta\",\"1\",{\"name\":\"description\",\"content\":\"Srila Prabhupada''s books online\"}],[\"$\",\"meta\",\"2\",{\"name\":\"application-name\",\"content\":\"Vedabase\"}],[\"$\",\"link\",\"3\",{\"rel\":\"author\",\"href\":\"https://vedabase.io\"}],[\"$\",\"meta\",\"4\",{\"name\":\"author\",\"content\":\"A.C. Bhaktivedanta Swami - Srila Prabhupada\"}],[\"$\",\"meta\",\"5\",{\"name\":\"keywords\",\"content\":\"Srila Prabhupada,Krsna,Krishna,bhakti,devotion\"}],[\"$\",\"meta\",\"6\",{\"name\":\"creator\",\"content\":\"Prahlad Nrsimha das\"}]]\n"])self.__next_f.push([1,"25:T483,Puṇya means that which is not decomposed; puṇya is original. Everything in the material world has a certain flavor or fragrance, as the flavor and fragrance in a flower, or in the earth, in water, in fire, in air, etc. The uncontaminated flavor, the original flavor, which permeates everything, is Kṛṣṇa. Similarly, everything has a particular original taste, and this taste can be changed by the mixture of chemicals. So everything original has some smell, some fragrance and some taste. Vibhāvasu means fire. Without fire we cannot run factories, we cannot cook, etc., and that fire is Kṛṣṇa. The heat in the fire is Kṛṣṇa. According to Vedic medicine, indigestion is due to a low temperature in the belly. So even for digestion fire is needed. In Kṛṣṇa consciousness we become aware that earth, water, fire, air and every active principle, all chemicals and all material elements are due to Kṛṣṇa. The duration of man’s life is also due to Kṛṣṇa. Therefore by the grace of Kṛṣṇa, man can prolong his life or diminish it. So Kṛṣṇa consciousness is active in every sphere."])self.__next_f.push([1,"23:[\"$\",\"div\",null,{\"className\":\"flex flex-col min-h-screen text-vb-normal-text\",\"children\":[[\"$\",\"$L1a\",null,{\"className\":\"w-full left-0 z-30 bg-vb-body/95\",\"children\":[\"$\",\"$L1b\",null,{\"mainMenu\":\"$L24\",\"page\":{\"id\":2160,\"meta\":{\"type\":\"books.Verse\",\"slug\":\"9\",\"show_in_menus\":false,\"seo_title\":\"\",\"search_description\":\"\",\"first_published_at\":null,\"alias_of\":null,\"locale\":\"en\"},\"title\":\"TEXT 9\",\"advanced_view_url_path\":\"/en/library/bg/7/advanced-view/#bb1915\",\"language_menu\":[{\"display_name\":\"አማርኛ (Ethiopian)\",\"language_code\":\"am\",\"enabled\":false,\"url_path\":\"/am/\"},{\"display_name\":\"Български (Bulgarian)\",\"language_code\":\"bg\",\"enabled\":true,\"url_path\":\"/bg/library/bg/7/9/\"},{\"display_name\":\"Čeština (Czech)\",\"language_code\":\"cs\",\"enabled\":true,\"url_path\":\"/cs/library/bg/7/9/\"},{\"display_name\":\"Dansk (Danish)\",\"language_code\":\"da\",\"enabled\":true,\"url_path\":\"/da/library/bg/7/9/\"},{\"display_name\":\"Deutsch (German)\",\"language_code\":\"de\",\"enabled\":true,\"url_path\":\"/de/library/bg/7/9/\"},{\"display_name\":\"English\",\"language_code\":\"en\",\"enabled\":true,\"url_path\":\"/en/library/bg/7/9/\"},{\"display_name\":\"Español (Spanish)\",\"language_code\":\"es\",\"enabled\":true,\"url_path\":\"/es/library/bg/7/9/\"},{\"display_name\":\"Eesti keel (Estonian)\",\"language_code\":\"et\",\"enabled\":true,\"url_path\":\"/et/library/bg/7/9/\"},{\"display_name\":\"Suomen kieli (Finnish)\",\"language_code\":\"fi\",\"enabled\":false,\"url_path\":\"/fi/\"},{\"display_name\":\"Français (French)\",\"language_code\":\"fr\",\"enabled\":true,\"url_path\":\"/fr/library/bg/7/9/\"},{\"display_name\":\"Hrvatski (Croatian)